using ExtractorOLE.DTOs;

namespace ExtractorOLE.Benchmarks
{
    /// <summary>
    /// Catalog of the 12 fixed benchmark inputs (6 formats x 10MB / ~100MB tiers) generated by
    /// T-f0963fc3 into the gitignored <c>samples/benchmark/</c> directory.
    /// </summary>
    internal static class BenchmarkSamples
    {
        public const string RegenerateCommand = "dotnet run -c Release --project SampleGenerator -- --benchmark";
        public const string SamplesDirEnvVar = "OLE_BENCHMARK_SAMPLES_DIR";

        // Ids are "<format>-<tier>", e.g. "docx-10mb"; the file is samples/benchmark/benchmark-<tier>.<format>.
        private static readonly (string Ext, OfficeMimeTypeEnum Mime)[] Formats =
        {
            ("docx", OfficeMimeTypeEnum.Word),
            ("xlsx", OfficeMimeTypeEnum.Excel),
            ("pptx", OfficeMimeTypeEnum.PowerPoint),
            ("doc", OfficeMimeTypeEnum.WordLegacy),
            ("xls", OfficeMimeTypeEnum.ExcelLegacy),
            ("ppt", OfficeMimeTypeEnum.PowerPointLegacy),
        };

        public static IEnumerable<string> Ids(string tier) => Formats.Select(f => $"{f.Ext}-{tier}");

        public static OfficeMimeTypeEnum MimeFor(string id) =>
            Formats.Single(f => f.Ext == id[..id.IndexOf('-')]).Mime;

        public static string PathFor(string id)
        {
            int dash = id.IndexOf('-');
            return Path.Combine(ResolveDir(), $"benchmark-{id[(dash + 1)..]}.{id[..dash]}");
        }

        /// <summary>Length in bytes of the sample file, or null when it cannot be found.</summary>
        public static long? SizeOf(string id)
        {
            try { return new FileInfo(PathFor(id)).Length; }
            catch (Exception) { return null; }
        }

        /// <summary>Fails clearly (with the regenerate command) if the sample directory is missing.</summary>
        public static string ResolveDir()
        {
            string? overridden = Environment.GetEnvironmentVariable(SamplesDirEnvVar);
            if (!string.IsNullOrWhiteSpace(overridden))
            {
                if (Directory.Exists(overridden)) return overridden;
                throw Missing($"{SamplesDirEnvVar}='{overridden}' does not exist");
            }

            // Walk up from the working dir and the binary dir (BenchmarkDotNet child processes
            // run from a generated folder under the repo) looking for samples/benchmark.
            foreach (string start in new[] { Directory.GetCurrentDirectory(), AppContext.BaseDirectory })
            {
                for (var dir = new DirectoryInfo(start); dir != null; dir = dir.Parent)
                {
                    string candidate = Path.Combine(dir.FullName, "samples", "benchmark");
                    if (Directory.Exists(candidate)) return candidate;
                }
            }
            throw Missing("samples/benchmark/ was not found in any parent directory");
        }

        private static InvalidOperationException Missing(string reason) => new(
            $"Benchmark samples not available: {reason}. Generate the 12 fixed inputs (about 1 minute, " +
            $"verifies SHA-256s against samples/manifest.json) from the repo root with:{Environment.NewLine}" +
            $"    {RegenerateCommand}{Environment.NewLine}" +
            $"or point {SamplesDirEnvVar} at a directory containing benchmark-10mb.* and benchmark-100mb.*.");
    }
}
